  // ---- updates: changes are batched, and applied together in a microtask

  #requestUpdate() {
    this.#pending ??= Promise.resolve().then(() => this.#update());
  }

  #update() {
    this.#pending = null;
    // Off the page, nothing updates; it catches up when it's back (connectedCallback).
    if (!this.#started || !this.isConnected) return;
    for (const update of this.#updates) update();
  }

  /** Resolves once pending changes are on the page. */
  get updateComplete() {
    return this.#pending ?? Promise.resolve();
  }

  /** Fires one of the element's events: it bubbles; a before… event can be cancelled. */
  #fire(name, detail) {
    return this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, cancelable: name.startsWith("before") }));
  }
